    const na=next.angle ?? angle, no=next.offset ?? offset;
    if(na!==angle){const target=spec.targetRelation==='parallel'?spec.baseAngle:(spec.baseAngle+90)%180; const dir=moveRelation(angle,na,target); if(dir) onEvent?.({control:'angle',dir,kind:'efficient'});}
