    {[A,B,C,D].map((p,i)=><g key={i}><circle cx={X(p[0])} cy={Y(p[1])} r={i===3?9:6} fill={i===3?PALETTE.tangerine:PALETTE.ink}/><text x={X(p[0])+10} y={Y(p[1])-8} fontWeight="900" fontSize="12">{'ABCD'[i]}({p[0]},{p[1]})</text></g>)}
